```python
# 推斷：資料表=零件清單（表頭第2列）｜欄位=項次、品名、新版料號、新版數量、新版M/S、舊版料號、舊版數量、舊版M/S｜主檔=零件清單｜鍵=新版M/S｜篩選=新版M/S≠"OK"｜輸出=新工作表

import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["零件清單"]

# 表頭列
header_row = 2

# 用第1列的合併群組標題來消歧重複欄名（如 M/S）
group_for_col = {}
for merged_range in ws.merged_cells.ranges:
    # 只處理涵蓋第 1 列的合併範圍
    if merged_range.min_row <= 1 <= merged_range.max_row:
        group_value = ws.cell(merged_range.min_row, merged_range.min_col).value
        for col in range(merged_range.min_col, merged_range.max_col + 1):
            group_for_col[col] = group_value

# 讀取第2列欄名
headers = {}
for col in range(1, ws.max_column + 1):
    headers[col] = ws.cell(header_row, col).value

# 找出重複的欄名，並建立「群組+欄名」的有效欄名對照
from collections import Counter
header_name_count = Counter(headers.values())
effective_name = {}
for col, name in headers.items():
    if header_name_count[name] > 1:
        effective_name[col] = f"{group_for_col.get(col, '')} {name}".strip()
    else:
        effective_name[col] = name

# 定位「新版 M/S」所在欄
filter_col = None
for col, eff_name in effective_name.items():
    if eff_name == "新版 M/S":
        filter_col = col
        break

if filter_col is None:
    raise ValueError("找不到「新版 M/S」欄位")

# 收集符合條件的資料列（新版 M/S 不是 "OK"）
filtered_rows = []
for row in range(header_row + 1, ws.max_row + 1):
    ms_value = ws.cell(row, filter_col).value
    if ms_value != "OK":
        filtered_rows.append([ws.cell(row, col).value for col in range(1, ws.max_column + 1)])

# 建立新工作表
new_sheet_name = "新版M/S異常"
if new_sheet_name in wb.sheetnames:
    del wb[new_sheet_name]

new_ws = wb.create_sheet(title=new_sheet_name)

# 寫入第2列欄名
new_ws.append([headers[col] for col in range(1, ws.max_column + 1)])

# 寫入篩選後的資料
for row_data in filtered_rows:
    new_ws.append(row_data)

wb.save(OUTPUT_PATH)
```

```python
# 目標：從「主件表」中挑出「耐候」欄位值不是「良品」的資料，建立新工作表，只保留 項次、料號、品名、耐候
import openpyxl

wb = openpyxl.load_workbook(INPUT_PATH)
ws = wb["主件表"]

target_fields = ["項次", "料號", "品名", "耐候"]

# 自動偵測標頭列位置（可能分散在第 1、2 列，也可能在第 3 列）
header_rows = set()
field_location = {}  # field -> (row, col)

scan_limit = min(ws.max_row, 20)
for r in range(1, scan_limit + 1):
    for c in range(1, ws.max_column + 1):
        val = ws.cell(r, c).value
        if val is None:
            continue
        text = str(val).strip()
        if text in target_fields:
            header_rows.add(r)
            field_location[text] = (r, c)

if not header_rows:
    raise ValueError("無法偵測到標頭列")

deepest_header_row = max(header_rows)
data_start_row = deepest_header_row + 1

# 建立「欄位名稱 -> 欄號」對照：優先使用最底層標頭列的值，若空白則往上層找
header_map = {}
for c in range(1, ws.max_column + 1):
    for r in sorted(header_rows, reverse=True):
        val = ws.cell(r, c).value
        if val is not None and str(val).strip():
            header_map[str(val).strip()] = c
            break

# 確認目標欄位都存在
for f in target_fields:
    if f not in header_map:
        raise ValueError(f"工作表中找不到欄位：{f}")

# 挑選「耐候」不是「良品」的資料列
bad_rows = []
for r in range(data_start_row, ws.max_row + 1):
    weather_cell = ws.cell(r, header_map["耐候"]).value
    weather_val = "" if weather_cell is None else str(weather_cell).strip()
    if weather_val != "良品":
        record = {}
        for f in target_fields:
            v = ws.cell(r, header_map[f]).value
            record[f] = "" if v is None else v
        bad_rows.append(record)

# 建立新工作表
new_ws_name = "耐候非良品"
if new_ws_name in wb.sheetnames:
    # 若已存在則先移除，避免衝突
    del wb[new_ws_name]
new_ws = wb.create_sheet(title=new_ws_name)

# 寫入標頭
for c, f in enumerate(target_fields, start=1):
    new_ws.cell(row=1, column=c, value=f)

# 寫入資料
for r_idx, row in enumerate(bad_rows, start=2):
    for c_idx, f in enumerate(target_fields, start=1):
        new_ws.cell(row=r_idx, column=c_idx, value=row[f])

wb.save(OUTPUT_PATH)
```
